10	
11	/**
12	 * Assigns the new owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256
13	 * over {@code normalizedLastName + '|' + postcode}. Because the identifier is a pure function of the
14	 * last name and postcode, every owner with the same last name and postcode derives the same value and
15	 * so belongs to the same household automatically — there is no linking step and no back-fill.
16	 *
17	 * <p>The last name is normalized (trimmed, internal whitespace collapsed, lower-cased) before hashing,
18	 * so trivially different spellings map to one household. The identifier keys off the postcode alone,
19	 * not the free-text address, so a household needs a postcode: when the request has no postcode the
20	 * owner has no household and {@code householdId} is left null.
21	 *
22	 * <p>Note the change from earlier behaviour: {@code sharesHousehold} no longer creates the household
23	 * link (the link is now automatic); it only bypasses the household-duplicate block in
24	 * {@link EnsureHouseholdUnique}.
25	 *
26	 * <p>Runs after {@link BuildOwner} (so the entity, its last name and postcode exist) and before both
27	 * {@link EnsureHouseholdUnique} and {@link SaveOwner}, mutating the not-yet-persisted owner in place.
28	 */
29	public class AssignHouseholdId {
30	
31	    public void service(@Val Owner owner) {
32	        String postcode = owner.getPostcode();
33	        if (postcode == null || postcode.isBlank()) {
34	            return; // no postcode -> no household
35	        }
36	        String lastName = normalize(owner.getLastName());
37	        owner.setHouseholdId(stableId(lastName, postcode.trim()));
38	    }
39	
40	    /** Trim, collapse internal whitespace to a single space and lower-case for comparison. */
41	    private static String normalize(String value) {
42	        if (value == null) {
43	            return "";
44	        }
45	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
46	    }
47	
48	    /** First 12 hex characters of SHA-256 over the normalized last name and the postcode. */
49	    private static String stableId(String lastName, String postcode) {
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256")
52	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
53	            StringBuilder sb = new StringBuilder(digest.length * 2);
54	            for (byte b : digest) {
55	                sb.append(String.format("%02x", b));
56	            }
57	            return sb.substring(0, 12);
58	        }
59	        catch (NoSuchAlgorithmException ex) {
60	            throw new IllegalStateException("SHA-256 not available", ex);
61	        }
62	    }
63	}
