3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} at creation.
11	 * Points start at 0 and accumulate: +2 when an email is present, +1 when the owner's
12	 * {@code namesakeCount} is 0, +2 for a household of 3 or more (its {@code householdSize}) and +3 for
13	 * tenure over 365 days (the days elapsed since the owner's {@code registrationDate}). The points are
14	 * then mapped to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. Both fields are
15	 * stored on the owner.
16	 *
17	 * <p>Runs after {@link AssignHouseholdSize} and {@link AssignNamesakeCount} (so the household and
18	 * namesake snapshots exist) and before {@link SaveOwner}, mutating the not-yet-persisted owner in
19	 * place.
20	 */
21	public class AssignMembershipLevel {
22	
23	    private static final long TENURE_DAYS_FOR_POINTS = 365;
24	
25	    public void service(@Val Owner owner) {
26	        int points = 0;
27	
28	        String email = owner.getEmail();
29	        if (email != null && !email.isEmpty()) {
30	            points += 2;
31	        }
32	        Integer namesakeCount = owner.getNamesakeCount();
33	        if (namesakeCount != null && namesakeCount == 0) {
34	            points += 1;
35	        }
36	        Integer householdSize = owner.getHouseholdSize();
37	        if (householdSize != null && householdSize >= 3) {
38	            points += 2;
39	        }
40	        LocalDate registrationDate = owner.getRegistrationDate();
41	        if (registrationDate != null) {
42	            long tenureDays = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
43	            if (tenureDays > TENURE_DAYS_FOR_POINTS) {
44	                points += 3;
45	            }
46	        }
47	
48	        owner.setMembershipPoints(points);
49	        owner.setMembershipLevel(levelFor(points));
50	    }
51	
52	    private static int levelFor(int points) {
53	        if (points <= 1) {
54	            return 1;
55	        }
56	        if (points <= 3) {
57	            return 2;
58	        }
59	        if (points <= 5) {
60	            return 3;
61	        }
62	        return 4;
63	    }
64	}
